"use client";

import { useRef } from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";

type HeroProps = {
  title: string;
  subtitle: string;
};

const ENTRANCE = {
  duration: 0.4,
  stagger: 0.05,
  distance: 20,
  ease: "power3.out",
} as const;

export default function Hero({ title, subtitle }: HeroProps) {
  const heroRef = useRef<HTMLElement>(null);

  useGSAP(
    () => {
      const elements =
        heroRef.current?.querySelectorAll<HTMLElement>("[data-hero-reveal]");

      if (!elements?.length) return;

      const reducedMotion = window.matchMedia(
        "(prefers-reduced-motion: reduce)",
      ).matches;

      if (reducedMotion) {
        gsap.set(elements, {
          clearProps: "opacity,transform",
        });

        return;
      }

      gsap.fromTo(
        elements,
        {
          opacity: 0,
          y: ENTRANCE.distance,
        },
        {
          opacity: 1,
          y: 0,
          duration: ENTRANCE.duration,
          stagger: ENTRANCE.stagger,
          ease: ENTRANCE.ease,
          clearProps: "opacity,transform",
        },
      );
    },
    { scope: heroRef },
  );

  return (
    <section
      ref={heroRef}
      aria-labelledby="hero-title"
      className="relative isolate flex min-h-svh items-center overflow-hidden bg-[#10100f] px-6 py-24 text-[#f4f1e8] sm:px-10 lg:px-16"
    >
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 -z-10 bg-[radial-gradient(circle_at_75%_25%,rgba(220,255,92,0.12),transparent_34%)]"
      />

      <div className="mx-auto w-full max-w-7xl">
        <div className="max-w-4xl">
          <h1
            id="hero-title"
            data-hero-reveal
            style={{ opacity: 0, transform: "translate3d(0, 20px, 0)" }}
            className="text-balance text-5xl leading-[0.95] font-semibold tracking-[-0.045em] sm:text-7xl lg:text-[7.5rem]"
          >
            {title}
          </h1>

          <p
            data-hero-reveal
            style={{ opacity: 0, transform: "translate3d(0, 20px, 0)" }}
            className="mt-8 max-w-2xl text-pretty text-lg leading-relaxed text-[#f4f1e8]/65 sm:text-xl"
          >
            {subtitle}
          </p>
        </div>
      </div>
    </section>
  );
}
```

Uso:

```tsx
<Hero
  title="Construimos experiencias que dejan marca."
  subtitle="Diseño y tecnología trabajando juntos para convertir una buena idea en un producto memorable."
/>
```

El estado inicial vive en el propio markup para evitar el flash previo a GSAP. Solo se animan `transform` y `opacity`, y `prefers-reduced-motion` deja el contenido visible sin movimiento.
